const express = require('express');
const execa = require('execa');
const { Delegate } = require('../models/delegate');

const app = express();

app.post('/api/events/delegates/:delegateId/render-badge', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Verify delegate ownership
  const delegate = await Delegate.findOne({
    where: {
      id: req.params.delegateId,
      userId: req.user.id
    }
  });

  if (!delegate && req.user.role !== 'EVENT_ORGANIZER') {
    return res.status(403).json({ error: 'Access denied: delegate registration belongs to another attendee' });
  }

  try {
    const { stdout } = await execa('node', [
      './jobs/render-badge.js',
      '--delegate-id',
      req.params.delegateId
    ]);

    const data = JSON.parse(stdout);
    res.json({
      delegateId: req.params.delegateId,
      badgePdfUrl: data.badgeUrl
    });
  } catch (err) {
    res.status(500).json({ error: 'Badge generation failed' });
  }
});

app.listen(3388);
